dbutils.widgets.text('bronze_catalog', '', 'Bronze catalog')
dbutils.widgets.text('silver_catalog', '', 'Silver catalog')
dbutils.widgets.text('gold_catalog', '', 'Gold catalog')
dbutils.widgets.text('bundle_root', '', 'Bundle files root (set by the job)')

bronze_catalog = dbutils.widgets.get('bronze_catalog')
silver_catalog = dbutils.widgets.get('silver_catalog')
gold_catalog = dbutils.widgets.get('gold_catalog')
bundle_root = dbutils.widgets.get('bundle_root')

# COMMAND ----------

# MAGIC %md
# MAGIC ## Shared library

# COMMAND ----------

import os
import sys

# The shared library is the bundle's src/ folder. bundle_root is
# set by the job; interactive runs fall back to the repo layout.
LIBRARY = (os.path.join(bundle_root, "src") if bundle_root
           else os.path.abspath(os.path.join("..", "..", "src")))
if LIBRARY not in sys.path:
    sys.path.append(LIBRARY)

from databricks_de_common import ops  # noqa: E402

# COMMAND ----------

# MAGIC %md
# MAGIC ## Tables

# COMMAND ----------

# (layer, schema.Table) for every table the kit builds.
TABLES = [
    ('silver', 'policy_admin.Agent'),
    ('silver', 'policy_admin.Policy'),
    ('silver', 'sales.NewBusinessPolicy'),
    ('gold', 'distribution.DimAgent'),
    ('gold', 'sales.FactNewBusiness'),
    ('gold', 'ops.DataQualityResult'),
]
RETAIN_HOURS = 168

# COMMAND ----------

# MAGIC %md
# MAGIC ## Run

# COMMAND ----------

CATALOGS = {"silver": silver_catalog, "gold": gold_catalog}
ops.maintain_tables(spark, [f"{CATALOGS[layer]}.{key}"
                            for layer, key in TABLES], RETAIN_HOURS)
